/** Frame 4614 -- generated by the template lab from Figma node 538:39682
 *  (Frame 4614). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- cta/shop-now, offer, lead;
 *    board copy, editable -- past-season-styles, memorial-day, sale;
 *    photos -- image/photo; brand slots -- brand/0, brand/1, brand/2, brand/3.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { BrandMark } from '../../../../../render/templates/BrandMark';
import { FigmaLayers, FigmaText, FigmaStroke, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const FRAME_4614_538_39682_FIGMA = {
  "cta/shop-now": "538:39685", // cta: Shop Now
  "past-season-styles": "I538:39690;21584:46496", // text: *Past season styles.
  "offer": "538:39696", // offer: 60% OFF
  "lead": "538:39697", // lead: UP\u2028TO
  "memorial-day": "538:39700", // text: MEMORIAL DAY
  "sale": "538:39703", // text: SALE
  "cta/cta": "538:39684", // pill: CTA
  "rab/rab-white": "I538:39687;876:3882", // graphic: Rab / White
  "patagonia/patagonia-white": "I538:39690;21584:46497;876:3734", // graphic: Patagonia / White
  "brand-logo-frame/brand-logo": "538:39692", // graphic: Brand Logo
  "art/vector-741": "538:39694", // graphic: Vector 741
  "image/photo": "538:39683", // photo: image 3737
  "brand/0": "538:39687", // brand: Rab
  "brand/1": "538:39689", // brand: Brand Logo
  "brand/2": "538:39690", // brand: Patagonia
  "brand/3": "538:39693", // brand: Osprey *NEW
} as const;

export function Frame4614_538_39682({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [FRAME_4614_538_39682_FIGMA["cta/shop-now"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/cta/shop-now`} contract="lab.cta" layout={layout}
      text={asset.copy.cta || l.text!.chars} />,
    [FRAME_4614_538_39682_FIGMA["past-season-styles"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/past-season-styles`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4614_538_39682_FIGMA["offer"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/offer`} contract="lab.offer" layout={layout}
      text={asset.copy.offer || l.text!.chars} />,
    [FRAME_4614_538_39682_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [FRAME_4614_538_39682_FIGMA["memorial-day"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/memorial-day`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4614_538_39682_FIGMA["sale"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/sale`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_4614_538_39682_FIGMA["cta/cta"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cta/cta/mark`} src="/graphics/named-sale-pill-470x120-16vaikd.svg" fill="#F14221" layout={layout} />
      {board({ bare: true })}
    </>,
    [FRAME_4614_538_39682_FIGMA["rab/rab-white"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/rab/rab-white/mark`} src="/graphics/named-sale-rab-white-ob0ntm.svg"
      fill="#FFFFFF" layout={layout} />,
    [FRAME_4614_538_39682_FIGMA["patagonia/patagonia-white"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/patagonia/patagonia-white/mark`} src="/graphics/named-sale-patagonia-white-1c3d2d6.svg"
      fill="#FFFFFF" layout={layout} />,
    [FRAME_4614_538_39682_FIGMA["brand-logo-frame/brand-logo"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/brand-logo-frame/brand-logo/mark`} src="/graphics/named-sale-brand-logo-1ukenxj.svg"
      fill="#FFFFFF" layout={layout} />,
    [FRAME_4614_538_39682_FIGMA["art/vector-741"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/vector-741/mark`} src="/graphics/named-sale-vector-741-1dd84nb.svg"
      fill="#F14221" layout={layout} />,
    [FRAME_4614_538_39682_FIGMA["image/photo"]]: (l, box) => {
      const img = l.images?.[0] && layout.assets?.[l.images[0].ref];
      const crop = img && l.crop ? cropOf(l.crop, [l.w, l.h], [img.w, img.h]) : undefined;
      // The board's fade, kept for whatever photo fills the slot.
      const fade = l.images?.[0]?.opacity;
      return <>
        <Picture id={`${id}/image/photo`} zone={zone} initialSrc={img?.src} slot
          focus={crop?.focus} initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={l.crop}
          style={{ ...box, overflow: 'hidden', borderRadius: l.radius, clipPath: l.path ? `path("${l.path}")` : undefined, opacity: fade ?? box.opacity }} />
        <FigmaStroke l={l} box={box} />
      </>;
    },
    // The board's logo until the brief names a brand.
    [FRAME_4614_538_39682_FIGMA["brand/0"]]: (l, box, _n, board) => asset.media.brands?.[0]
      ? <BrandMark id={`${id}/brand/0`} name={asset.media.brands[0]} fallback="/logos/brand-rab.svg"
          style={{ ...box, objectFit: 'contain' }} />
      : board(),
    // The board's logo until the brief names a brand.
    [FRAME_4614_538_39682_FIGMA["brand/1"]]: (l, box, _n, board) => asset.media.brands?.[1]
      ? <BrandMark id={`${id}/brand/1`} name={asset.media.brands[1]} fallback="/logos/brand-the-north-face.svg"
          style={{ ...box, objectFit: 'contain' }} />
      : board(),
    // The board's logo until the brief names a brand.
    [FRAME_4614_538_39682_FIGMA["brand/2"]]: (l, box, _n, board) => asset.media.brands?.[2]
      ? <BrandMark id={`${id}/brand/2`} name={asset.media.brands[2]} fallback="/logos/brand-patagonia.svg"
          style={{ ...box, objectFit: 'contain' }} />
      : board(),
    // The board's logo until the brief names a brand.
    [FRAME_4614_538_39682_FIGMA["brand/3"]]: (l, box, _n, board) => asset.media.brands?.[3]
      ? <BrandMark id={`${id}/brand/3`} name={asset.media.brands[3]} fallback="/logos/brand-osprey.svg"
          style={{ ...box, objectFit: 'contain' }} />
      : board(),
  };
  const [w, h] = layout.size;
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <FigmaLayers layout={layout} slots={slots} nudges={NUDGE} />
  </Ground>;
}
